import { useEffect, useId, useRef, useState } from "react";
import "./CodeCard.css";

export interface CodeCardProps {
  title: string;
  code: string;
  onCopy: () => void;
}

type CopyStatus = "idle" | "copied" | "error";

export function CodeCard({ title, code, onCopy }: CodeCardProps) {
  const titleId = useId();
  const [status, setStatus] = useState<CopyStatus>("idle");
  const resetTimer = useRef<number | undefined>(undefined);

  useEffect(() => {
    return () => window.clearTimeout(resetTimer.current);
  }, []);

  async function handleCopy() {
    try {
      await navigator.clipboard.writeText(code);
      setStatus("copied");
      onCopy();
    } catch {
      setStatus("error");
    }
    window.clearTimeout(resetTimer.current);
    resetTimer.current = window.setTimeout(() => setStatus("idle"), 2000);
  }

  const message =
    status === "copied"
      ? "Copied to clipboard."
      : status === "error"
        ? "Copy failed. Select the snippet and copy it manually."
        : "";

  return (
    <section className="codecard" aria-labelledby={titleId}>
      <header className="codecard__header">
        <h2 id={titleId} className="codecard__title">
          {title}
        </h2>
        <button
          type="button"
          className="codecard__copy"
          onClick={handleCopy}
        >
          Copy
        </button>
      </header>

      <pre className="codecard__pre" tabIndex={0} aria-labelledby={titleId}>
        <code className="codecard__code">{code}</code>
      </pre>

      <p
        className={`codecard__status${message ? " codecard__status--visible" : ""}`}
        role="status"
        aria-live="polite"
      >
        {message}
      </p>
    </section>
  );
}
