    --codecard-button-bg: #272c36;
    --codecard-button-text: #e4e6eb;
    --codecard-button-hover: #323846;
    --codecard-focus: #8ab4f0;
    --codecard-error: #f0a08c;
  }
}

.codecard {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 16px 18px;
  background: var(--codecard-surface);
  border: 1px solid var(--codecard-border);
  border-radius: var(--codecard-radius);
  color: var(--codecard-text);
}

.codecard__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.codecard__title {
  margin: 0;
  font-size: 0.95rem;
  font-weight: 600;
  line-height: 1.3;
}

.codecard__copy {
  flex-shrink: 0;
  padding: 6px 14px;
  font: inherit;
  font-size: 0.85rem;
  font-weight: 500;
  color: var(--codecard-button-text);
  background: var(--codecard-button-bg);
  border: 1px solid var(--codecard-border);
  border-radius: 6px;
  cursor: pointer;
  transition: background-color 0.15s ease;
}

.codecard__copy:hover {
  background: var(--codecard-button-hover);
}

.codecard__copy:active {
  transform: translateY(1px);
}

.codecard__pre {
  margin: 0;
  padding: 12px 14px;
  overflow-x: auto;
  background: var(--codecard-code-bg);
  border: 1px solid var(--codecard-border);
  border-radius: 8px;
  font-family: ui-monospace, "SFMono-Regular", Menlo, Consolas, "Liberation Mono", monospace;
  font-size: 0.85rem;
  line-height: 1.55;
  white-space: pre;
  tab-size: 2;
}

.codecard__code {
  font: inherit;
  color: var(--codecard-code-text);
}

/* Visible focus for keyboard users, on both the button and the scrollable block */
.codecard__copy:focus-visible,
.codecard__pre:focus-visible {
  outline: 2px solid var(--codecard-focus);
  outline-offset: 2px;
}

/* Live region: reserved space so the layout does not jump when the message appears */
.codecard__status {
  margin: 0;
  min-height: 1.2em;
  font-size: 0.8rem;
  color: var(--codecard-muted);
  opacity: 0;
  transition: opacity 0.2s ease;
}

.codecard__status--visible {
  opacity: 1;
}

.codecard__status--error,
.codecard__status:has(+ *) {
  color: var(--codecard-muted);
}

@media (prefers-reduced-motion: reduce) {
  .codecard__copy,
  .codecard__status {
    transition: none;
  }
}
